      "content": "/**\n * @melandlabs/memory-store — SDK entry point.\n *\n * Wires up a top-level `MemoryStore` facade combining the raw message\n * manager, the unified search facade, and vector index helpers. Hosts\n * that want a non-web backend (CLI daemon, custom server) can use\n * this as the only entry point.\n */\n\nimport { type SQLiteVsaStore, getSQLiteVsaStore } from \"@melandlabs/sqlite\";\nimport type { MemoryStoreConfig } from \"./config\";\nimport type { SearchRuntimeContext } from \"./search/applicability\";\nimport type { ApplyConsolidateInput, ApplyConsolidateOutput } from \"./search/apply-reflect\";\nimport { type UnifiedSearch, createUnifiedSearch } from \"./search/unified-search\";\nimport type { SearchInput, SearchOutput } from \"./search/utilities\";\nexport {\n\tcreateExtractiveEvidenceSelector,\n\ttype EvidenceSelector,\n\ttype EvidenceSelectorOptions,\n} from \"./search/evidence-selector\";\nimport { type VsaRecallFacade, createVsaRecall } from \"./search/vsa\";\nimport {\n\ttype RawMessageStore,\n\tconfigureRawMessageStore,\n\tcreateRawMessageStore,\n\tgetRawMessageManager,\n} from \"./storage/raw-message-store\";\nimport { resolveSQLiteRawMessageDbPath } from \"./storage/sqlite-raw-message-store\";\n\nexport interface MemoryStore {\n\t/** Underlying raw-message store (sqlite vs postgres). */\n\traw: RawMessageStore;\n\t/**\n\t * Unified read entry point. Cross-source retrieval (memory +\n\t * insights + knowledge + summaries) with RRF merge, reasoning\n\t * strategies (`rewrite` / `iterative`), date filtering, and\n\t * lexical fallback. Set `synthesize: true` to opt into the LLM\n\t * synthesis path (formerly `reflect()`).\n\t *\n\t * The optional second argument is trusted in-process context. Omitting it\n\t * preserves legacy unscoped behaviour; an explicit empty applicability list\n\t * requests global-only retrieval.\n\t *\n\t * Use `store.consolidate()` for the agentic write-back loop.\n\t */\n\tsearch(input: SearchInput, runtimeContext?: SearchRuntimeContext): Promise<SearchOutput>;\n\t/** Resolve the active raw-message manager. */\n\tgetRawMessageManager: typeof getRawMessageManager;\n\t/**\n\t * @deprecated Use `store.search(input)` instead. Forwarding shim\n\t * kept for one release window.\n\t */\n\tsearchUnifiedMemory: UnifiedSearch[\"searchUnifiedMemory\"];\n\t/**\n\t * @deprecated Use `store.search({ ...input, sources: [\"memory\"] })`\n\t * and read `.results` instead.\n\t */\n\tsearchRawMemorySemantically: UnifiedSearch[\"searchRawMemorySemantically\"];\n\t/**\n\t * Agentic write-back: gathers evidence, vets a consolidation plan\n\t * with the LLM, persists via the attached graph store +\n\t * soft-deprecates via the storage adapter. The `graphStore` and\n\t * `storage` fields are forwarded from this `MemoryStore` instance\n\t * when the caller omits them on the input.\n\t */\n\tconsolidate(input: ApplyConsolidateInput): Promise<ApplyConsolidateOutput>;\n\t/**\n\t * Optional write-back graph store. Set via `attachMemoryGraphStore`;\n\t * consumers can read it for diagnostic / replay tooling. Absent when\n\t * the host has not wired one in.\n\t */\n\tgraphStore?: import(\"@melandlabs/memory-consolidation\").MemoryGraphStoreWithOperationHistory;\n\t/**\n\t * Optional storage adapter carrying `deprecateRecords`. Forwarded into\n\t * `consolidate` when callers want deprecation writes without\n\t * attaching a full graph store.\n\t */\n\tstorage?: import(\"@melandlabs/memory-consolidation\").MemoryStorageAdapterLike;\n\t/**\n\t * Vector Symbolic Architecture facade. Always available — backed by\n\t * the same SQLite DB the raw-message manager uses. Routes through its\n\t * own `vsa_facts` table; never mixed into the unified search.\n\t *\n\t *   - `vsaStoreFact(input)` — persist a (role, filler) binding.\n\t *   - `vsaRecall(input)`    — rebuild memory vector + best-match cleanup.\n\t *   - `vsaListFacts(input)` — read-side projection (no vectors).\n\t *   - `vsaForget(input)`    — soft-delete by id.\n\t */\n\tvsa: VsaRecallFacade;\n}\n\nexport async function createMemoryStore(config: MemoryStoreConfig = {}): Promise<MemoryStore> {\n\tconst dbPath =\n\t\tconfig.dbPath ?? (config.db && \"path\" in config.db ? (config.db as { path?: string }).path : undefined);\n\tconst raw = createRawMessageStore({ env: config.env, dbPath });\n\t// Forward the host-configured `logger` into the unified-search facade so\n\t// `consolidate` honours it instead of always using `console`.\n\tconst search = createUnifiedSearch({ ...config.unified, logger: config.logger });\n\n\t// Make the legacy `getRawMessageManager()` module-level facade\n\t// point at this configuration so callers that don't go through\n\t// `createMemoryStore` still get the right backend.\n\tconfigureRawMessageStore(config);\n\n\t// Mutable wiring shared between the write path (`consolidate`) and the\n\t// opt-in `attachMemoryGraphStore` helper. A holder object (rather than two\n\t// captured `const`s) is required so that `attachMemoryGraphStore` — which\n\t// assigns `store.graphStore` — actually changes what `consolidate`\n\t// forwards. Previously it only overwrote a dead property and the attached\n\t// graph store was silently ignored, leaving `consolidate` in\n\t// deprecate-only mode no matter what.\n\tconst wiring: {\n\t\tgraphStore?: import(\"@melandlabs/memory-consolidation\").MemoryGraphStoreWithOperationHistory;\n\t\tstorage?: import(\"@melandlabs/memory-consolidation\").MemoryStorageAdapterLike;\n\t} = {\n\t\tgraphStore: config.graphStore,\n\t\tstorage: config.storage,\n\t};\n\n\t// VSA facade — lazily open the SQLite VSA store. Shares the same DB\n\t// file as the raw-message store, so `init()` is a no-op if the schema\n\t// has already been brought up by `raw.init()`. Resolve the DB path\n\t// here because `getSQLiteVsaStore` lives in `@melandlabs/sqlite`\n\t// (which `memory-store` depends on) and can't import the env-aware\n\t// `resolveSQLiteRawMessageDbPath` helper without forming a cycle.\n\tconst vsaDbPath =\n\t\tconfig.dbPath ??\n\t\t(config.db && \"path\" in config.db ? (config.db as { path?: string }).path : undefined) ??\n\t\tresolveSQLiteRawMessageDbPath();\n\tconst vsaStorage: SQLiteVsaStore = await getSQLiteVsaStore({\n\t\tdbPath: vsaDbPath,\n\t});\n\tconst vsa = createVsaRecall(vsaStorage);\n\n\tconst applyConsolidate = (input: ApplyConsolidateInput) =>\n\t\tsearch.consolidate({\n\t\t\t...input,\n\t\t\tgraphStore: input.graphStore ?? wiring.graphStore,\n\t\t\tstorage: input.storage ?? wiring.storage,\n\t\t});\n\n\tconst store: MemoryStore = {\n\t\traw,\n\t\t// Flat search verb — `search({ synthesize: true })` opts into the\n\t\t// read-only LLM synthesis path.\n\t\tsearch: search.search,\n\t\tvsa,\n\t\tgetRawMessageManager,\n\t\tsearchUnifiedMemory: search.searchUnifiedMemory,\n\t\tsearchRawMemorySemantically: search.searchRawMemorySemantically,\n\t\tconsolidate: applyConsolidate,\n\t\tget graphStore() {\n\t\t\treturn wiring.graphStore;\n\t\t},\n\t\tset graphStore(value) {\n\t\t\twiring.graphStore = value;\n\t\t},\n\t\tget storage() {\n\t\t\treturn wiring.storage;\n\t\t},\n\t\tset storage(value) {\n\t\t\twiring.storage = value;\n\t\t},\n\t};\n\n\treturn store;\n}\n\nexport type { MemoryStoreConfig };\nexport type { SearchRuntimeContext } from \"./search/applicability\";\nexport {\n\tcreateRawMessageStore,\n\tgetRawMessageManager,\n\tisRawMessageStorageAvailable,\n\tgetRawMessageStorageBackend,\n\tcloseRawMessageStore,\n\ttype RawMessageStorageBackend,\n\ttype RawMessageStorageManagerWithSearch,\n} from \"./storage/raw-message-store\";\nexport {\n\tregisterPostgresFactory,\n\tclearPostgresFactory,\n\thasPostgresFactory,\n\tresolvePostgresFactory,\n\ttype PostgresFactoryFn,\n\ttype PostgresRawMessageManagerLike,\n} from \"./storage/postgres-raw-message-factory\";\nexport {\n\tcreateUnifiedSearch,\n\ttype UnifiedSearch,\n} from \"./search/unified-search\";\nexport {\n\ttype ApplyConsolidateInput,\n\ttype ApplyConsolidateOutput,\n\tapplyReflectedPlan,\n} from \"./search/apply-reflect\";\nexport {\n\ttype AttachMemoryGraphStoreInput,\n\tattachMemoryGraphStore,\n} from \"./memory-store-graph\";\nexport type {\n\tUnifiedMemorySearchInput,\n\tUnifiedMemorySearchOutput,\n\tUnifiedMemorySearchResult,\n\tUnifiedMemorySearchSource,\n\tUnifiedMemorySearchWarning,\n\tUnifiedMemoryReasoningStrategy,\n\tUnifiedMemoryReasoningInfo,\n} from \"./search/utilities\";\nexport type {\n\tHitChannel,\n\tHitSignals,\n\tSearchInput,\n\tSearchOutput,\n\tSearchSource,\n\tSearchTier,\n\tSearchEvidence,\n\tSearchEvidenceProvenance,\n\tSearchSourceState,\n\tUnifiedMemoryMergeStrategy,\n\tUnifiedMemoryRankedList,\n} from \"./search/utilities\";\nexport {\n\tlistNameToChannel,\n\tmaterializeSignals,\n\tmergeUnifiedMemorySearchResultsRrf,\n} from \"./search/utilities\";\nexport {\n\ttype DeriveInput,\n\ttype DeriveOutput,\n\ttype DeriveWarning,\n\tderiveFacts,\n} from \"./search/derive\";\nexport {\n\ttype DistillInput,\n\ttype DistillOutput,\n\ttype DistillWarning,\n\tdistillRawMessage,\n} from \"./search/distill\";\nexport {\n\tclampUnifiedMemorySearchLimit,\n\tclampUnifiedMemorySearchThreshold,\n\tisRawMemorySemanticResult,\n\tmergeUnifiedMemorySearchResults,\n\tnormalizeUnifiedMemoryReasoningStrategy,\n\tnormalizeUnifiedMemorySearchSources,\n\ttoKnowledgeResult,\n\ttoMemoryResult,\n} from \"./search/utilities\";\nexport {\n\tcreateUserVoiceRewriter,\n\tcreateIdentityRewriter,\n\ttype QueryRewriter,\n\ttype QueryRewriterInput,\n\ttype QueryRewriterOptions,\n} from \"./search/query-rewriter\";\nexport {\n\tcreateIterativeRecallPlanner,\n\tcreateIdentityIterativePlanner,\n\ttype IterativeRecallCandidate,\n\ttype IterativeRecallCompletionOptions,\n\ttype IterativeRecallExecutor,\n\ttype IterativeRecallPlanner,\n\ttype IterativeRecallPlannerOptions,\n\ttype IterativeRecallResult,\n\ttype IterativeRecallSearchRequest,\n\ttype IterativeRecallSearchResult,\n\ttype IterativeRecallStats,\n} from \"./search/iterative-recall\";\nexport {\n\tcreatePeerProfile,\n\ttype PeerProfile,\n\ttype PeerRelationship,\n\ttype PeerProfileDeps,\n\ttype PeerPosting,\n\ttype PeerProfileFacade,\n} from \"./search/peer-profile\";\nexport type {\n\tMemoryStoreDb,\n\tMemoryStoreEnv,\n\tVectorBackend,\n\tEmbedQueryFn,\n\tUnifiedSearchKnowledgeResult,\n\tUnifiedSearchInsightsResult,\n\tUnifiedSearchTextResult,\n\tUnifiedSearchReasoningDeps,\n\tSearchProviderApplicabilityInput,\n} from \"./config\";\nexport type { RawMessage } from \"./config\";\nexport {\n\tcreateVsaRecall,\n\ttype VsaRecallFacade,\n} from \"./search/vsa\";\nexport type {\n\tStoreVsaFactInput,\n\tStoreVsaFactOutput,\n\tVsaFact,\n\tVsaFactSummary,\n\tVsaFactStorage,\n\tVsaForgetInput,\n\tVsaForgetOutput,\n\tVsaListInput,\n\tVsaRecallInput,\n\tVsaRecallOutput,\n\tVsaRecallScore,\n\tVsaVocabularyEntry,\n\tEntityEdge,\n\tEntityKind,\n\tDerivedFact,\n\tDerivedKind,\n} from \"@melandlabs/contracts\";\nexport {\n\tgetSQLiteVsaStore,\n\tcloseSQLiteVsaStore,\n\ttype SQLiteVsaStore,\n\ttype SQLiteVsaStoreOptions,\n} from \"@melandlabs/sqlite\";\n"
    },
    {
      "path": "packages/memory-store/src/memory-store-graph.ts",
      "content": "/**\n * `attachMemoryGraphStore` — opt-in helper for hosts that want to wire\n * a memory graph store onto an existing `MemoryStore` without going\n * through `createMemoryStore({ graphStore })`.\n *\n * Usage:\n * ```ts\n * const store = await createMemoryStore();\n * attachMemoryGraphStore(store, {\n *   storage: indexedDbStorage,\n *   ownerScope: { userId: \"u-42\" },\n * });\n * ```\n *\n * Returns the same `MemoryStore` reference for chaining. When\n * `storage.compareAndSwapGraphLedger` is missing, no graph store is\n * attached and a warning is emitted via the supplied logger — callers\n * may still run `consolidate`, but it will skip `persistPlan` and\n * emit a `reflect_apply_graph_store_not_configured` warning. The\n * deprecation path through `storage.deprecateRecords` continues to\n * work as long as a `MemoryStorageAdapter` is wired elsewhere.\n */\n\nimport {\n\ttype RawMessageGraphEvolutionStorage,\n\tcreateRawMessageMemoryGraphStore,\n} from \"@melandlabs/indexeddb\";\nimport type { OwnerScope } from \"@melandlabs/memory-consolidation\";\nimport type { MemoryStore } from \"./index\";\n\nexport interface AttachMemoryGraphStoreInput {\n\tstorage: RawMessageGraphEvolutionStorage;\n\townerScope: OwnerScope;\n\tbotId?: string;\n\tnow?: () => number;\n\t/**\n\t * Optional logger; falls back to `console`. The helper does not log on\n\t * the happy path; it only warns when `compareAndSwapGraphLedger` is\n\t * missing on the storage.\n\t */\n\tlogger?: Pick<Console, \"warn\">;\n}\n\nexport function attachMemoryGraphStore(store: MemoryStore, input: AttachMemoryGraphStoreInput): MemoryStore {\n\tconst logger = input.logger ?? console;\n\tif (typeof input.storage.compareAndSwapGraphLedger !== \"function\") {\n\t\tlogger.warn?.(\n\t\t\t\"[memory-store] attachMemoryGraphStore: storage is missing `compareAndSwapGraphLedger`; no graph store attached.\",\n\t\t);\n\t\treturn store;\n\t}\n\n\tconst graphStore = createRawMessageMemoryGraphStore({\n\t\tstorage: input.storage,\n\t\townerScope: input.ownerScope,\n\t\tbotId: input.botId,\n\t\tnow: input.now,\n\t});\n\n\tstore.graphStore = graphStore;\n\treturn store;\n}\n"
    },
    {
      "path": "packages/memory-store/src/search/apply-reflect.ts",
      "content": "/**\n * `applyReflectedPlan` — agentic write-back facade.\n *\n * Composes the read-only `search({ synthesize })` evidence pipeline with\n * the `applyReflectedConsolidationPlan` write-side so a single call\n * gathers evidence (raw + summaries + insights + knowledge), vets the\n * plan with the LLM (optional), and persists the result to the graph\n * store + storage.\n *\n * Behaviour parity with `search({ synthesize: true })`:\n *   - Reuses the same gather-evidence pipeline so the answer + evidence\n *     are identical to a read-only search call.\n *   - Honours `peerFilter` via the same scope check used by the unified\n *     read pipeline.\n *   - LLM `complete` is the same `deps.reasoning.complete` the read-only\n *     path uses — no new injection point.\n *\n * Write path:\n *   - When `graphStore` is set (either passed in or attached via\n *     `attachMemoryGraphStore`), persists the graph plan via\n *     `MemoryGraphStoreWithOperationHistory.persistPlan`.\n *   - Always runs `storage.deprecateRecords` for `deprecate` entries — the\n *     deprecation chain is the critical path, so it runs even when the\n *     graph store is missing (with a `reflect_apply_graph_store_not_configured`\n *     warning).\n */\n\nimport type { MemoryStorageAdapter } from \"@melandlabs/ai/memory\";\nimport type { Peer } from \"@melandlabs/contracts/peer\";\nimport type {\n\tApplyReflectApplyInput,\n\tMemoryConsolidationPlan,\n\tMemoryEvidenceRecord,\n\tMemoryGraphStoreWithOperationHistory,\n\tMemoryGraphUpdateResult,\n\tMemoryStorageAdapterLike,\n\tOwnerScope,\n\tReflectApplyClusterKeyFn,\n} from \"@melandlabs/memory-consolidation\";\nimport { applyReflectedConsolidationPlan } from \"@melandlabs/memory-consolidation\";\nimport type { UnifiedSearchDeps } from \"../config\";\nimport { createUnifiedSearch } from \"./unified-search\";\nimport type { SearchEvidence, SearchInput, SearchSource, SearchTier } from \"./utilities\";\nimport {\n\ttype UnifiedMemorySearchWarning,\n\tclampUnifiedMemorySearchLimit,\n\tclampUnifiedMemorySearchThreshold,\n} from \"./utilities\";\n\nexport interface ApplyConsolidateInput {\n\tuserId: string;\n\tquery: string;\n\townerScope: OwnerScope;\n\tbotIds?: string[];\n\tdateFrom?: string;\n\tdateTo?: string;\n\ttiers?: ReadonlyArray<SearchTier>;\n\tlimit?: number;\n\tthreshold?: number;\n\tplan?: MemoryConsolidationPlan;\n\tdryRun?: boolean;\n\texpectedVersion?: string;\n\tllmPlanReview?: { maxTokens?: number };\n\tauthToken?: string;\n\tpeerFilter?: ReadonlyArray<Peer>;\n\t/**\n\t * Cluster-key selector forwarded to `buildMemoryConsolidationPlan`.\n\t * When omitted, callers should pass a pre-built `plan`.\n\t */\n\tgetClusterKey?: ReflectApplyClusterKeyFn;\n\t/**\n\t * Optional storage adapter — falls back to `store.raw` when wired up by\n\t * `createMemoryStore`. Required when no `graphStore` is attached and the\n\t * caller still wants `deprecateRecords` writes.\n\t */\n\tstorage?: MemoryStorageAdapterLike;\n\tgraphStore?: MemoryGraphStoreWithOperationHistory;\n}\n\nexport interface ApplyConsolidateOutput {\n\tanswer: string;\n\tplan: MemoryConsolidationPlan;\n\tpersistenceResult?: MemoryGraphUpdateResult;\n\tdeprecationCounts?: Array<{ supersededBySummaryId: string; count: number }>;\n\twarnings: UnifiedMemorySearchWarning[];\n\tapplied: boolean;\n\tevidence: SearchEvidence[];\n}\n\nconst DEFAULT_TIERS: SearchTier[] = [\"summary\", \"raw\", \"insight\", \"knowledge\"];\n\ninterface MemoryStoreLike {\n\tgraphStore?: MemoryGraphStoreWithOperationHistory;\n\tstorage?: MemoryStorageAdapterLike | MemoryStorageAdapter;\n}\n\ntype MemoryEvidenceTier = MemoryEvidenceRecord[\"tier\"];\n\n/**\n * Map the read-side source/tier vocabulary onto the consolidation\n * `MemoryEvidenceTier` vocabulary. Accepts the full `SearchEvidence.source`\n * union (both `SearchSource` and `SearchTier` shapes), so anything that\n * isn't a `raw` / `summary` hit falls through to `mid`.\n */\nfunction reflectTierToEvidenceTier(source: SearchSource | SearchTier): MemoryEvidenceTier {\n\tswitch (source) {\n\t\tcase \"raw\":\n\t\t\treturn \"short\";\n\t\tcase \"summary\":\n\t\t\treturn \"long\";\n\t\tdefault:\n\t\t\treturn \"mid\";\n\t}\n}\n\nfunction toMemoryEvidenceRecord(input: SearchEvidence, fallbackUserId: string): MemoryEvidenceRecord {\n\tconst tier = reflectTierToEvidenceTier(input.source);\n\tconst timestamp = input.timestamp ?? Date.now();\n\treturn {\n\t\tid: input.id,\n\t\tuserId: fallbackUserId,\n\t\ttimestamp,\n\t\ttier,\n\t\ttext: input.snippet,\n\t\tmetadata: {\n\t\t\tsource: input.source,\n\t\t\tscore: input.score,\n\t\t\t...(input.timestamp !== undefined ? { originalTimestamp: input.timestamp } : {}),\n\t\t},\n\t};\n}\n\nexport async function applyReflectedPlan(\n\tdeps: UnifiedSearchDeps,\n\tstore: MemoryStoreLike,\n\tinput: ApplyConsolidateInput,\n\t_logger: Pick<Console, \"log\" | \"warn\" | \"error\">,\n): Promise<ApplyConsolidateOutput> {\n\tconst query = input.query.trim();\n\tconst warnings: UnifiedMemorySearchWarning[] = [];\n\tconst limit = clampUnifiedMemorySearchLimit(input.limit);\n\tconst threshold = clampUnifiedMemorySearchThreshold(input.threshold);\n\tconst tiers = input.tiers && input.tiers.length > 0 ? input.tiers : DEFAULT_TIERS;\n\n\tconst searchInput: SearchInput = {\n\t\tuserId: input.userId,\n\t\tquery,\n\t\tbotIds: input.botIds,\n\t\tdateFrom: input.dateFrom,\n\t\tdateTo: input.dateTo,\n\t\ttiers,\n\t\tlimit,\n\t\tthreshold,\n\t\tauthToken: input.authToken,\n\t\tpeerFilter: input.peerFilter,\n\t\tsynthesize: true,\n\t};\n\n\tconst search = createUnifiedSearch(deps);\n\tconst result = await search.search(searchInput);\n\twarnings.push(...result.warnings);\n\n\tconst evidence: SearchEvidence[] = result.evidence.map((item) => ({\n\t\tid: item.id,\n\t\tsource: (item.source as SearchTier) ?? \"raw\",\n\t\tsnippet: item.snippet,\n\t\tscore: item.score,\n\t\ttimestamp: item.timestamp,\n\t\tprovenance: item.provenance,\n\t}));\n\n\tconst records = evidence.map((item) => toMemoryEvidenceRecord(item, input.userId));\n\n\tconst applyInput: ApplyReflectApplyInput = {\n\t\tuserId: input.userId,\n\t\townerScope: input.ownerScope,\n\t\trecords,\n\t\tplan: input.plan,\n\t\tdryRun: input.dryRun,\n\t\texpectedVersion: input.expectedVersion,\n\t\tgetClusterKey: input.getClusterKey ?? defaultClusterKey,\n\t\tllmReview: deps.reasoning?.complete\n\t\t\t? {\n\t\t\t\t\tcomplete: deps.reasoning.complete,\n\t\t\t\t\tmaxTokens: input.llmPlanReview?.maxTokens,\n\t\t\t\t}\n\t\t\t: undefined,\n\t\tgraphStore: input.graphStore ?? store.graphStore,\n\t\tstorage: input.storage ?? store.storage,\n\t};\n\n\tconst applyOutput = await applyReflectedConsolidationPlan(applyInput);\n\tfor (const warning of applyOutput.warnings) {\n\t\twarnings.push({\n\t\t\tsource: \"memory\",\n\t\t\tcode: warning.code,\n\t\t\tmessage: warning.message,\n\t\t});\n\t}\n\n\tconst summaryAnswer = makePlanSummary(applyOutput.plan);\n\n\treturn {\n\t\tanswer: result.answer ? `${result.answer}\\n\\nPlan summary:\\n${summaryAnswer}` : summaryAnswer,\n\t\tplan: applyOutput.plan,\n\t\tpersistenceResult: applyOutput.persistenceResult,\n\t\tdeprecationCounts: applyOutput.deprecationCounts,\n\t\twarnings,\n\t\tapplied: applyOutput.applied,\n\t\tevidence,\n\t};\n}\n\nfunction defaultClusterKey(record: MemoryEvidenceRecord): string | undefined {\n\treturn record.text ?? record.id;\n}\n\nfunction makePlanSummary(plan: MemoryConsolidationPlan): string {\n\tconst lines: string[] = [];\n\tconst counts = {\n\t\tpreserve: plan.actions.preserve.length,\n\t\tobserve: plan.actions.observe.length,\n\t\tdecay: plan.actions.decay.length,\n\t\tdeprecate: plan.actions.deprecate.length,\n\t};\n\tlines.push(\n\t\t`- preserve=${counts.preserve} observe=${counts.observe} decay=${counts.decay} deprecate=${counts.deprecate}`,\n\t);\n\tfor (const entry of plan.actions.deprecate.slice(0, 5)) {\n\t\tlines.push(\n\t\t\t`  deprecate ${entry.recordIds.length} record(s) from cluster ${entry.clusterKey} -> ${\n\t\t\t\tentry.supersededBySummaryId ?? entry.winningClusterKey\n\t\t\t}`,\n\t\t);\n\t}\n\treturn lines.join(\"\\n\");\n}\n\n// Re-export so consumers only need a single import surface.\nexport type { MemoryStorageAdapter };\n"
    },
    {
      "path": "packages/memory-store/src/search/unified-search.ts",
      "content": "/**\n * Unified semantic search facade.\n *\n * Cross-source search over raw messages (always), insights, and\n * uploaded knowledge documents. The host wires up the cross-domain\n * dependencies via `UnifiedSearchDeps` so this module stays\n * framework-agnostic.\n *\n * The public entry point is `search(input, runtimeContext?)` — a single method. Set\n * `synthesize: true` to opt into the LLM synthesis step.\n */\n\nimport type { Peer } from \"@melandlabs/contracts/peer\";\nimport type { UnifiedSearchDeps } from \"../config\";\nimport { isRawMessageChromaEnabled, searchRawMessagesWithChroma } from \"../storage/chroma-memory-index\";\nimport { isRawMessageStorageAvailable } from \"../storage/raw-message-store\";\nimport {\n\ttype ResolvedSearchRuntimeContext,\n\ttype SearchRuntimeContext,\n\tresolveSearchRuntimeContext,\n} from \"./applicability\";\nimport { type ApplyConsolidateInput, type ApplyConsolidateOutput, applyReflectedPlan } from \"./apply-reflect\";\nimport { boundedSearchOperation } from \"./execution-budget\";\nimport { gatherSummaries, resolveSearchScopePeers, synthesizeAnswer } from \"./gather-evidence\";\nimport type {\n\tIterativeRecallCandidate,\n\tIterativeRecallSearchRequest,\n\tIterativeRecallSearchResult,\n} from \"./iterative-recall\";\nimport { mergeMatchedEvidence, withMatchedEvidence } from \"./matched-evidence\";\nimport { presentMessageContext } from \"./message-context\";\nimport { applyReranker } from \"./reranker\";\nimport {\n\ttype SearchEvidence,\n\ttype SearchInput,\n\ttype SearchOutput,\n\ttype SearchSource,\n\ttype SearchSourceState,\n\ttype SearchTier,\n\ttype SessionNeighborExpansionOptions,\n\ttype UnifiedMemoryMergeStrategy,\n\ttype UnifiedMemoryRankedList,\n\ttype UnifiedMemoryReasoningInfo,\n\ttype UnifiedMemoryReasoningStrategy,\n\ttype UnifiedMemorySearchInput,\n\ttype UnifiedMemorySearchOutput,\n\ttype UnifiedMemorySearchResult,\n\ttype UnifiedMemorySearchSource,\n\ttype UnifiedMemorySearchWarning,\n\tclampUnifiedMemorySearchLimit,\n\tclampUnifiedMemorySearchThreshold,\n\tderiveLexicalKeywords,\n\tisRawMemorySemanticResult,\n\tmaterializeSignals,\n\tmergeSearchResultProvenance,\n\tmergeUnifiedMemorySearchResults,\n\tmergeUnifiedMemorySearchResultsRrf,\n\tnormalizeUnifiedMemoryMergeStrategy,\n\tnormalizeUnifiedMemoryReasoningStrategy,\n\tnormalizeUnifiedMemorySearchSources,\n\tresolveScopePeer,\n\ttoKnowledgeResult,\n\ttoMemoryResult,\n} from \"./utilities\";\n\nexport type {\n\tHitChannel,\n\tHitSignals,\n\tUnifiedMemoryRrfWeights,\n\tUnifiedMemoryMergeStrategy,\n\tUnifiedMemoryRankedList,\n\tUnifiedMemoryReasoningStrategy,\n\tUnifiedMemorySearchInput,\n\tUnifiedMemorySearchOutput,\n\tUnifiedMemorySearchResult,\n\tUnifiedMemorySearchSource,\n\tUnifiedMemorySearchWarning,\n\tSessionNeighborExpansionOptions,\n\tSearchInput,\n\tSearchOutput,\n\tSearchSource,\n\tSearchTier,\n\tSearchEvidence,\n\tSearchEvidenceProvenance,\n\tSearchSourceState,\n} from \"./utilities\";\nexport type { SearchRuntimeContext } from \"./applicability\";\n\nexport {\n\tclampUnifiedMemorySearchLimit,\n\tclampUnifiedMemorySearchThreshold,\n\tderiveLexicalKeywords,\n\tisRawMemorySemanticResult,\n\tlistNameToChannel,\n\tmaterializeSignals,\n\tmergeUnifiedMemorySearchResults,\n\tmergeUnifiedMemorySearchResultsRrf,\n\tnormalizeUnifiedMemoryMergeStrategy,\n\tnormalizeUnifiedMemoryReasoningStrategy,\n\tnormalizeUnifiedMemorySearchSources,\n\ttoKnowledgeResult,\n\ttoMemoryResult,\n} from \"./utilities\";\n\nexport interface UnifiedSearch {\n\t/**\n\t * Single unified read entry point. Set `synthesize: true` to opt into\n\t * LLM synthesis. The optional second argument is trusted in-process\n\t * applicability context and is intentionally separate from `SearchInput`.\n\t */\n\tsearch(input: SearchInput, runtimeContext?: SearchRuntimeContext): Promise<SearchOutput>;\n\t/**\n\t * @deprecated Use `search(input)` instead. Forwarding shim kept for\n\t * one release window.\n\t */\n\tsearchUnifiedMemory(input: UnifiedMemorySearchInput): Promise<UnifiedMemorySearchOutput>;\n\t/**\n\t * @deprecated Use `search({ ...input, sources: [\"memory\"] })` and\n\t * read `.results` instead.\n\t */\n\tsearchRawMemorySemantically(input: UnifiedMemorySearchInput): Promise<UnifiedMemorySearchResult[]>;\n\t/**\n\t * Agentic write-back: runs the same evidence pipeline as `search`,\n\t * then builds a memory-consolidation plan, optionally asks the LLM\n\t * to veto unsafe entries, and persists via the attached graph store\n\t * (when present) + soft-deprecates superseded records via the storage\n\t * adapter. See `./apply-reflect.ts` for the contract and degradation\n\t * rules.\n\t */\n\tconsolidate(input: ApplyConsolidateInput): Promise<ApplyConsolidateOutput>;\n}\n\n/**\n * Heuristic entity-keyword extractor: reuses the lexical tokenizer\n * and additionally pulls out capitalized proper-noun-shaped tokens\n * (≥ 3 chars, starting with an uppercase Latin letter). The intent is\n * to capture obvious named-entity mentions like \"Luna\", \"Acme\", \"Berlin\"\n * without committing to a full NER pipeline — the host's\n * `entitySearch` dep is responsible for any language-aware matching\n * beyond this surface.\n */\nfunction deriveEntityKeywords(query: string): string[] {\n\tconst proper = Array.from(new Set(query.match(/\\b[A-Z][a-zA-Z]{2,}\\b/g) ?? [])).map((w) => w.toLowerCase());\n\tconst lexical = deriveLexicalKeywords(query);\n\t// Preserve order while deduplicating.\n\tconst seen = new Set<string>();\n\tconst out: string[] = [];\n\tfor (const word of [...proper, ...lexical]) {\n\t\tif (word.length < 2) continue;\n\t\tif (seen.has(word)) continue;\n\t\tseen.add(word);\n\t\tout.push(word);\n\t}\n\treturn out.slice(0, 16);\n}\n\n/**\n * Run the host's `entitySearch` sub-query and project the matches\n * back into `UnifiedMemorySearchResult[]` so the outer merge can fuse\n * them with semantic + lexical channels via RRF.\n *\n * Returns `[]` when no entity keywords can be derived (e.g. the query\n * is short, all-lowercase, or numeric).\n */\nasync function runEntitySearchForQuery(\n\tdeps: UnifiedSearchDeps,\n\tinput: UnifiedMemorySearchInput,\n\tlimit: number,\n\tlogger: Pick<Console, \"warn\">,\n\tpeerPeers: ReadonlyArray<Peer> = [],\n\truntimeContext?: ResolvedSearchRuntimeContext,\n): Promise<UnifiedMemorySearchResult[]> {\n\tif (typeof deps.entitySearch !== \"function\") {\n\t\treturn [];\n\t}\n\tconst keywords = deriveEntityKeywords(input.query);\n\tif (keywords.length === 0) {\n\t\treturn [];\n\t}\n\ttry {\n\t\tconst entitySearch = deps.entitySearch;\n\t\tconst filters = input.botIds && input.botIds.length > 0 ? input.botIds : [undefined];\n\t\tconst matches = (\n\t\t\tawait Promise.all(\n\t\t\t\tfilters.map((botId) =>\n\t\t\t\t\tentitySearch({\n\t\t\t\t\t\tuserId: input.userId,\n\t\t\t\t\t\tkeywords,\n\t\t\t\t\t\tlimit: Math.ceil(limit / filters.length),\n\t\t\t\t\t\tbotId,\n\t\t\t\t\t\t...(peerPeers.length > 0 ? { peers: peerPeers } : {}),\n\t\t\t\t\t\t...(runtimeContext ?? {}),\n\t\t\t\t\t}),\n\t\t\t\t),\n\t\t\t)\n\t\t).flat();\n\t\treturn matches\n\t\t\t.filter(\n\t\t\t\t(m): m is { messageId: string; label: string; score: number } =>\n\t\t\t\t\ttypeof m?.messageId === \"string\" && typeof m?.label === \"string\" && typeof m?.score === \"number\",\n\t\t\t)\n\t\t\t.map((m) => ({\n\t\t\t\ttype: \"memory\" as const,\n\t\t\t\tid: m.messageId,\n\t\t\t\t// The host's `entitySearch` returns match ids + labels only,\n\t\t\t\t// so we surface the entity label as `content`. When the same\n\t\t\t\t// `messageId` is also returned by the semantic/lexical channel\n\t\t\t\t// (RRF path), the real message content is preserved via the\n\t\t\t\t// shared `(type, id)` key; otherwise callers can re-fetch the\n\t\t\t\t// original message by `id` (set in metadata as `sourceMessageId`).\n\t\t\t\tcontent: m.label,\n\t\t\t\tsimilarity: m.score,\n\t\t\t\tmetadata: {\n\t\t\t\t\tscoring: \"entity\",\n\t\t\t\t\tentityLabel: m.label,\n\t\t\t\t\tisEntityProjection: true,\n\t\t\t\t\tsourceMessageId: m.messageId,\n\t\t\t\t},\n\t\t\t}));\n\t} catch (error) {\n\t\tlogger.warn?.(\"[memory-store] entity search failed:\", error);\n\t\treturn [];\n\t}\n}\n\nfunction parseDateBoundary(value: string, role: \"from\" | \"to\"): number | undefined {\n\tconst trimmed = value.trim();\n\tif (!trimmed) {\n\t\treturn undefined;\n\t}\n\n\t// Date-only strings must be parsed in UTC to avoid timezone drift.\n\t// Date.parse(\"2024-05-15\") treats the value as local midnight, which can\n\t// shift the boundary by the host offset.\n\tconst dateOnlyMatch = trimmed.match(/^(\\d{4})-(\\d{2})-(\\d{2})$/);\n\tif (dateOnlyMatch) {\n\t\tconst year = Number.parseInt(dateOnlyMatch[1], 10);\n\t\tconst month = Number.parseInt(dateOnlyMatch[2], 10) - 1;\n\t\tconst day = Number.parseInt(dateOnlyMatch[3], 10);\n\t\tif (role === \"from\") {\n\t\t\treturn Date.UTC(year, month, day);\n\t\t}\n\t\t// Inclusive end of the day.\n\t\treturn Date.UTC(year, month, day + 1) - 1;\n\t}\n\n\tconst parsed = Date.parse(trimmed);\n\tif (Number.isNaN(parsed)) {\n\t\treturn undefined;\n\t}\n\treturn parsed;\n}\n\nfunction getCandidateTimestamp(metadata: Record<string, unknown>): number | undefined {\n\tfor (const key of [\"timestamp\", \"createdAt\", \"time\"]) {\n\t\tconst value = metadata[key];\n\t\tif (typeof value === \"number\") {\n\t\t\treturn value;\n\t\t}\n\t\tif (typeof value === \"string\") {\n\t\t\tconst parsed = Date.parse(value);\n\t\t\tif (!Number.isNaN(parsed)) {\n\t\t\t\treturn parsed;\n\t\t\t}\n\t\t}\n\t}\n\treturn undefined;\n}\n\nfunction filterByDateRange<T extends { metadata: Record<string, unknown> }>(\n\titems: T[],\n\tdateFrom?: string,\n\tdateTo?: string,\n): T[] {\n\tif (!dateFrom && !dateTo) {\n\t\treturn items;\n\t}\n\n\tconst fromMs = dateFrom ? parseDateBoundary(dateFrom, \"from\") : undefined;\n\tconst toMs = dateTo ? parseDateBoundary(dateTo, \"to\") : undefined;\n\tif (fromMs === undefined && toMs === undefined) {\n\t\treturn items;\n\t}\n\n\treturn items.filter((item) => {\n\t\tconst ts = getCandidateTimestamp(item.metadata);\n\t\tif (ts === undefined) {\n\t\t\treturn true;\n\t\t}\n\t\tif (fromMs !== undefined && ts < fromMs) {\n\t\t\treturn false;\n\t\t}\n\t\tif (toMs !== undefined && ts > toMs) {\n\t\t\treturn false;\n\t\t}\n\t\treturn true;\n\t});\n}\n\nfunction warnApplicabilityNotEnforced(warnings: UnifiedMemorySearchWarning[]): void {\n\tif (warnings.some((warning) => warning.code === \"memory_applicability_not_enforced\")) {\n\t\treturn;\n\t}\n\twarnings.push({\n\t\tsource: \"memory\",\n\t\tcode: \"memory_applicability_not_enforced\",\n\t\tmessage:\n\t\t\t\"Built-in raw-message retrieval was skipped because it cannot enforce the supplied applicability context. Configure an applicability-aware raw-message provider.\",\n\t});\n}\n\nfunction monotonicNow(): number {\n\tconst performanceNow = globalThis.performance?.now;\n\treturn typeof performanceNow === \"function\" ? performanceNow.call(globalThis.performance) : Date.now();\n}\n\nasync function embedQueryVariant(\n\tembedQuery: NonNullable<UnifiedSearchDeps[\"embedQuery\"]>,\n\tinput: UnifiedMemorySearchInput,\n\tquery: string,\n): Promise<number[]> {\n\treturn embedQuery({\n\t\tuserId: input.userId,\n\t\tquery,\n\t\tauthToken: input.authToken,\n\t});\n}\n\ninterface RetrievalExecution {\n\tcompleted: number;\n\tfailed: number;\n}\n\nasync function runSemanticSearchForEmbedding(\n\tdeps: UnifiedSearchDeps,\n\tinput: UnifiedMemorySearchInput,\n\tqueryEmbedding: number[],\n\tlimit: number,\n\tthreshold: number,\n\tlogger: Pick<Console, \"log\" | \"warn\">,\n\tpeerPeers: ReadonlyArray<Peer>,\n\twarnings: UnifiedMemorySearchWarning[],\n\truntimeContext?: ResolvedSearchRuntimeContext,\n\texecution?: RetrievalExecution,\n): Promise<UnifiedMemorySearchResult[]> {\n\tconst filters = input.botIds && input.botIds.length > 0 ? input.botIds.map((botId) => ({ botId })) : [{}];\n\tlet semantic: UnifiedMemorySearchResult[] = [];\n\n\tif (typeof deps.searchRawMessagesAnn === \"function\") {\n\t\tconst searchRawMessagesAnn = deps.searchRawMessagesAnn;\n\t\tconst factTypes = input.factTypes?.length ? input.factTypes : undefined;\n\t\tconst includeDeprecated = input.includeDeprecated === true;\n\t\tsemantic = (\n\t\t\tawait Promise.all(\n\t\t\t\tfilters.map((filter) =>\n\t\t\t\t\tsearchRawMessagesAnn({\n\t\t\t\t\t\tuserId: input.userId,\n\t\t\t\t\t\tqueryEmbedding,\n\t\t\t\t\t\tlimit,\n\t\t\t\t\t\tthreshold,\n\t\t\t\t\t\tbotId: \"botId\" in filter ? filter.botId : undefined,\n\t\t\t\t\t\tincludeDeprecated,\n\t\t\t\t\t\t...(input.asOf ? { asOf: input.asOf } : {}),\n\t\t\t\t\t\t...(peerPeers.length > 0 ? { peers: peerPeers } : {}),\n\t\t\t\t\t\t...(factTypes ? { factTypes } : {}),\n\t\t\t\t\t\t...(runtimeContext ?? {}),\n\t\t\t\t\t}),\n\t\t\t\t),\n\t\t\t)\n\t\t)\n\t\t\t.flat()\n\t\t\t.filter(isRawMemorySemanticResult)\n\t\t\t.map(toMemoryResult);\n\t} else if (runtimeContext === undefined && isRawMessageChromaEnabled()) {\n\t\ttry {\n\t\t\tsemantic = (\n\t\t\t\tawait Promise.all(\n\t\t\t\t\tfilters.map((filter) => {\n\t\t\t\t\t\tconst botId = \"botId\" in filter ? filter.botId : undefined;\n\t\t\t\t\t\treturn boundedSearchOperation(\n\t\t\t\t\t\t\tsearchRawMessagesWithChroma,\n\t\t\t\t\t\t\tdeps,\n\t\t\t\t\t\t)({\n\t\t\t\t\t\t\tuserId: input.userId,\n\t\t\t\t\t\t\tqueryEmbedding,\n\t\t\t\t\t\t\tlimit,\n\t\t\t\t\t\t\tthreshold,\n\t\t\t\t\t\t\tbotId,\n\t\t\t\t\t\t});\n\t\t\t\t\t}),\n\t\t\t\t)\n\t\t\t)\n\t\t\t\t.flat()\n\t\t\t\t.map(toMemoryResult);\n\t\t\tif (execution) execution.completed++;\n\t\t\tlogger.log?.(\"[memory-store] Raw message semantic search completed\", {\n\t\t\t\tbackend: \"chroma\",\n\t\t\t\tdimensions: queryEmbedding.length,\n\t\t\t\tcount: semantic.length,\n\t\t\t});\n\t\t} catch (error) {\n\t\t\tif (execution) execution.failed++;\n\t\t\tlogger.warn?.(\n\t\t\t\t\"[memory-store] Chroma raw message search failed; falling back to database search:\",\n\t\t\t\terror,\n\t\t\t);\n\t\t}\n\t}\n\n\tif (semantic.length === 0 && runtimeContext !== undefined && !deps.searchRawMessagesAnn) {\n\t\twarnApplicabilityNotEnforced(warnings);\n\t\treturn [];\n\t}\n\n\tif (semantic.length === 0 && typeof deps.searchRawMessagesAnn !== \"function\") {\n\t\ttry {\n\t\t\tconst { getRawMessageManager } = await import(\"../storage/raw-message-store\");\n\t\t\tconst manager = await getRawMessageManager();\n\t\t\tif (typeof manager.searchMessagesSemantically === \"function\") {\n\t\t\t\tconst factTypes = input.factTypes?.length ? input.factTypes : undefined;\n\t\t\t\tconst results = await boundedSearchOperation(\n\t\t\t\t\tmanager.searchMessagesSemantically.bind(manager),\n\t\t\t\t\tdeps,\n\t\t\t\t)({\n\t\t\t\t\tuserId: input.userId,\n\t\t\t\t\tqueryEmbedding,\n\t\t\t\t\tlimit,\n\t\t\t\t\tthreshold,\n\t\t\t\t\tincludeDeprecated: input.includeDeprecated === true,\n\t\t\t\t\t...(input.asOf ? { asOf: input.asOf } : {}),\n\t\t\t\t\t...(peerPeers.length > 0 ? { peers: peerPeers } : {}),\n\t\t\t\t\t...(factTypes ? { factTypes } : {}),\n\t\t\t\t});\n\t\t\t\tif (execution) execution.completed++;\n\t\t\t\tsemantic = (\n\t\t\t\t\tresults as Array<{\n\t\t\t\t\t\tid: string;\n\t\t\t\t\t\tcontent: string;\n\t\t\t\t\t\tsimilarity: number;\n\t\t\t\t\t\tmetadata?: Record<string, unknown>;\n\t\t\t\t\t}>\n\t\t\t\t).map((r) => ({\n\t\t\t\t\ttype: \"memory\" as const,\n\t\t\t\t\tid: r.id,\n\t\t\t\t\tcontent: r.content,\n\t\t\t\t\tsimilarity: r.similarity,\n\t\t\t\t\tmetadata: r.metadata ?? {},\n\t\t\t\t}));\n\t\t\t}\n\t\t} catch (error) {\n\t\t\tif (execution) execution.failed++;\n\t\t\tlogger.warn?.(\"[memory-store] SQLite semantic search failed:\", error);\n\t\t}\n\t}\n\n\treturn semantic;\n}\n\n/**\n * Merge several ranked lists of `id`-keyed hits into a single list where each\n * id appears at most once, keeping the entry with the highest `similarity`.\n * Generic over the hit shape; both `UnifiedMemorySearchResult` and\n * `IterativeRecallCandidate` qualify without a wrapper.\n */\nfunction mergeByMaxScore<\n\tT extends { id: string; content: string; similarity: number; metadata: Record<string, unknown> },\n>(lists: T[][]): T[] {\n\tconst best = new Map<string, T>();\n\tfor (const list of lists) {\n\t\tfor (const hit of list) {\n\t\t\tconst existing = best.get(hit.id);\n\t\t\tif (!existing) {\n\t\t\t\tbest.set(hit.id, hit);\n\t\t\t} else {\n\t\t\t\tconst preferred = hit.similarity > existing.similarity ? hit : existing;\n\t\t\t\tconst other = preferred === hit ? existing : hit;\n\t\t\t\tbest.set(hit.id, mergeMatchedEvidence(preferred, other));\n\t\t\t}\n\t\t}\n\t}\n\treturn Array.from(best.values()).sort((a, b) => b.similarity - a.similarity);\n}\n\nfunction dedupeChannelByParent(\n\thits: UnifiedMemorySearchResult[],\n\tchannel: string,\n): UnifiedMemorySearchResult[] {\n\tconst strongest = new Map<string, UnifiedMemorySearchResult>();\n\tfor (const [index, hit] of hits.entries()) {\n\t\tconst sourceMessageId = hit.metadata?.sourceMessageId;\n\t\tconst parentId =\n\t\t\ttypeof sourceMessageId === \"string\" && sourceMessageId.length > 0 ? sourceMessageId : hit.id;\n\t\tconst normalized =\n\t\t\thit.type === \"memory\"\n\t\t\t\t? withMatchedEvidence(hit.id !== parentId ? { ...hit, id: parentId } : hit, channel, index + 1)\n\t\t\t\t: hit;\n\t\tconst key = `${normalized.type}:${parentId}`;\n\t\tconst current = strongest.get(key);\n\t\tif (!current) {\n\t\t\tstrongest.set(key, normalized);\n\t\t} else {\n\t\t\tconst preferred = normalized.similarity > current.similarity ? normalized : current;\n\t\t\tconst other = preferred === normalized ? current : normalized;\n\t\t\tstrongest.set(\n\t\t\t\tkey,\n\t\t\t\tpreferred.type === \"memory\" && other.type === \"memory\"\n\t\t\t\t\t? mergeMatchedEvidence(preferred, other)\n\t\t\t\t\t: preferred,\n\t\t\t);\n\t\t}\n\t}\n\treturn [...strongest.values()].sort((a, b) => b.similarity - a.similarity);\n}\n\nfunction toIterativeRecallCandidate(hit: UnifiedMemorySearchResult): IterativeRecallCandidate {\n\treturn {\n\t\tid: hit.id,\n\t\tcontent: hit.content,\n\t\tsimilarity: hit.similarity,\n\t\tmetadata: hit.metadata,\n\t};\n}\n\nasync function runLexicalSearchForKeywords(\n\tdeps: UnifiedSearchDeps,\n\tinput: UnifiedMemorySearchInput,\n\tkeywords: string[],\n\tlimit: number,\n\tlogger: Pick<Console, \"warn\">,\n\tpeerPeers: ReadonlyArray<Peer>,\n\twarnings: UnifiedMemorySearchWarning[],\n\truntimeContext?: ResolvedSearchRuntimeContext,\n\texecution?: RetrievalExecution,\n): Promise<UnifiedMemorySearchResult[]> {\n\tif (keywords.length === 0) {\n\t\treturn [];\n\t}\n\n\tif (typeof deps.searchRawMessagesLexical === \"function\") {\n\t\ttry {\n\t\t\tconst filters = input.botIds && input.botIds.length > 0 ? input.botIds : [undefined];\n\t\t\tconst searchRawMessagesLexical = deps.searchRawMessagesLexical;\n\t\t\tconst factTypes = input.factTypes?.length ? input.factTypes : undefined;\n\t\t\tconst includeDeprecated = input.includeDeprecated === true;\n\t\t\treturn (\n\t\t\t\tawait Promise.all(\n\t\t\t\t\tfilters.map((botId) =>\n\t\t\t\t\t\tsearchRawMessagesLexical({\n\t\t\t\t\t\t\tuserId: input.userId,\n\t\t\t\t\t\t\tkeywords,\n\t\t\t\t\t\t\tlimit: Math.ceil(limit / filters.length),\n\t\t\t\t\t\t\tbotId,\n\t\t\t\t\t\t\tincludeDeprecated,\n\t\t\t\t\t\t\t...(input.asOf ? { asOf: input.asOf } : {}),\n\t\t\t\t\t\t\t...(peerPeers.length > 0 ? { peers: peerPeers } : {}),\n\t\t\t\t\t\t\t...(factTypes ? { factTypes } : {}),\n\t\t\t\t\t\t\t...(runtimeContext ?? {}),\n\t\t\t\t\t\t}),\n\t\t\t\t\t),\n\t\t\t\t)\n\t\t\t)\n\t\t\t\t.flat()\n\t\t\t\t.filter(isRawMemorySemanticResult)\n\t\t\t\t.map((hit) => ({\n\t\t\t\t\t...toMemoryResult(hit),\n\t\t\t\t\tmetadata: { ...hit.metadata, scoring: \"bm25\" },\n\t\t\t\t}));\n\t\t} catch (error) {\n\t\t\tlogger.warn?.(\"[memory-store] lexical memory search failed:\", error);\n\t\t\twarnings.push({\n\t\t\t\tsource: \"memory\",\n\t\t\t\tcode: \"memory_lexical_search_failed\",\n\t\t\t\tmessage: (error as Error).message ?? \"memory_lexical_search_failed\",\n\t\t\t});\n\t\t\tif (runtimeConte