dlabs/ai\": \"workspace:*\",\n\t\t\"@melandlabs/ai-rag\": \"workspace:*\",\n\t\t\"@melandlabs/audit\": \"workspace:*\",\n\t\t\"@melandlabs/contracts\": \"workspace:*\",\n\t\t\"@melandlabs/cron\": \"workspace:*\",\n\t\t\"@melandlabs/env-config\": \"workspace:*\",\n\t\t\"@melandlabs/indexeddb\": \"workspace:*\",\n\t\t\"@melandlabs/loop\": \"workspace:*\",\n\t\t\"@melandlabs/memory-store\": \"workspace:*\",\n\t\t\"@melandlabs/okf\": \"workspace:*\",\n\t\t\"@melandlabs/workspace\": \"workspace:*\",\n\t\t\"@melandlabs/rag\": \"workspace:*\",\n\t\t\"@melandlabs/search\": \"workspace:*\",\n\t\t\"@melandlabs/shared\": \"workspace:*\",\n\t\t\"@melandlabs/sqlite\": \"workspace:*\",\n\t\t\"@melandlabs/config\": \"workspace:*\",\n\t\t\"@melandlabs/voice-kokoro\": \"workspace:*\",\n\t\t\"@melandlabs/voice-whisper\": \"workspace:*\",\n\t\t\"@types/node\": \"^22.13.10\",\n\t\t\"tsup\": \"^8.0.0\",\n\t\t\"typescript\": \"^5.6.3\"\n\t},\n\t\"peerDependencies\": {\n\t\t\"@lancedb/lancedb\": \"^0.37.1\",\n\t\t\"@zilliz/milvus2-sdk-node\": \"^2.5.13\"\n\t},\n\t\"peerDependenciesMeta\": {\n\t\t\"@lancedb/lancedb\": {\n\t\t\t\"optional\": true\n\t\t},\n\t\t\"@zilliz/milvus2-sdk-node\": {\n\t\t\t\"optional\": true\n\t\t}\n\t},\n\t\"scripts\": {\n\t\t\"build\": \"tsup\",\n\t\t\"typecheck\": \"tsc --noEmit\",\n\t\t\"lint\": \"biome check .\",\n\t\t\"lint:fix\": \"biome check --write .\",\n\t\t\"test\": \"vitest run\",\n\t\t\"test:integration\": \"vitest run --config vitest.integration.config.ts\",\n\t\t\"test:watch\": \"vitest\"\n\t},\n\t\"exports\": {\n\t\t\".\": \"./dist/index.js\"\n\t}\n}\n"
