      "path": "packages/opencontext/src/index.ts",
      "content": "/**\n * @melandlabs/opencontext — single-package facade.\n *\n * Re-exports every public surface of the OpenContext runtime so a host\n * application needs only one dependency:\n *\n *     pnpm add @melandlabs/opencontext\n *     import { createMemoryStore } from \"@melandlabs/opencontext\";\n *\n * Underlying workspace packages (@melandlabs/contracts,\n * @melandlabs/memory-store, @melandlabs/rag, @melandlabs/loop,\n * @melandlabs/ai) are bundled at build time and do not appear as runtime\n * dependencies in the published manifest.\n */\n\n// ─── 1. Boundary contracts (types, schemas, errors, integration ids) ──────\n// `UserType` lives here canonically — the broader channel-aware union\n// from `@melandlabs/ai` is renamed to `AIUserType` in ai-reexport.ts to\n// avoid a duplicate-type conflict on this facade.\nexport * from \"@melandlabs/contracts\";\n\n// ─── 1b. App data directory paths (~/.opencontext or OPENCONTEXT_HOME) ────\nexport {\n\tOPENCONTEXT_HOME_ENV,\n\tgetOpenContextDir,\n\tgetOpenContextPath,\n\tensureOpenContextDir,\n} from \"@melandlabs/env-config\";\n\n// ─── 2. Memory store: the four-verb memory API + unified search ───────────\nexport {\n\tcreateMemoryStore,\n\tcreateRawMessageStore,\n\tgetRawMessageManager,\n\tisRawMessageStorageAvailable,\n\tgetRawMessageStorageBackend,\n\tcloseRawMessageStore,\n\tregisterPostgresFactory,\n\tclearPostgresFactory,\n\thasPostgresFactory,\n\tresolvePostgresFactory,\n\tclampUnifiedMemorySearchLimit,\n\tclampUnifiedMemorySearchThreshold,\n\tisRawMemorySemanticResult,\n\tmergeUnifiedMemorySearchResults,\n\tnormalizeUnifiedMemoryReasoningStrategy,\n\tnormalizeUnifiedMemorySearchSources,\n\ttoKnowledgeResult,\n\ttoMemoryResult,\n\tlistNameToChannel,\n\tmaterializeSignals,\n\tmergeUnifiedMemorySearchResultsRrf,\n\tdistillRawMessage,\n\tderiveFacts,\n\tcreateUserVoiceRewriter,\n\tcreateIdentityRewriter,\n\tcreateIterativeRecallPlanner,\n\tcreateIdentityIterativePlanner,\n} from \"@melandlabs/memory-store\";\n\nexport type {\n\tMemoryStore,\n\tMemoryStoreConfig,\n\tRawMessageStorageBackend,\n\tRawMessageStorageManagerWithSearch,\n\tPostgresFactoryFn,\n\tPostgresRawMessageManagerLike,\n\tUnifiedMemorySearchInput,\n\tUnifiedMemorySearchOutput,\n\tUnifiedMemorySearchResult,\n\tUnifiedMemorySearchSource,\n\tUnifiedMemorySearchWarning,\n\tUnifiedMemoryReasoningStrategy,\n\tUnifiedMemoryReasoningInfo,\n\tHitChannel,\n\tHitSignals,\n\tMemoryStoreDb,\n\tMemoryStoreEnv,\n\tVectorBackend,\n\tEmbedQueryFn,\n\tUnifiedSearchKnowledgeResult,\n\tUnifiedSearchInsightsResult,\n\tUnifiedSearchReasoningDeps,\n\tRawMessage,\n\tQueryRewriter,\n\tQueryRewriterInput,\n\tQueryRewriterOptions,\n\tIterativeRecallCandidate,\n\tIterativeRecallExecutor,\n\tIterativeRecallPlanner,\n\tIterativeRecallPlannerOptions,\n\tIterativeRecallResult,\n\tIterativeRecallSearchRequest,\n\tIterativeRecallSearchResult,\n\tIterativeRecallStats,\n\tDistillInput,\n\tDistillOutput,\n\tDistillWarning,\n\tDeriveInput,\n\tDeriveOutput,\n\tDeriveWarning,\n\tEntityEdge,\n\tEntityKind,\n\tDerivedFact,\n\tDerivedKind,\n} from \"@melandlabs/memory-store\";\n\n// Unified search facade (its own subpath entry).\nexport { createUnifiedSearch } from \"@melandlabs/memory-store/unified-search\";\nexport type { UnifiedSearch } from \"@melandlabs/memory-store/unified-search\";\n\n// Reasoning-backed memory retrieval providers.\nexport {\n\tcreateQueryRewriter,\n\tcreateIterativePlanner,\n\tcreateMemoryReasoningProviders,\n\tcreateDisabledMemoryReasoningProviders,\n} from \"./memory-reasoning\";\nexport type {\n\tReasoningModelOptions,\n\tMemoryReasoningProviders,\n} from \"./memory-reasoning\";\n\n// In-process context compaction factory for `IAgent.compactContext`. Hosts\n// attach the returned object to `AgentConfig.providerConfig.compactor`.\nexport { createCompactor, createDisabledCompactor } from \"./context-compaction\";\nexport type { CompactorModelOptions } from \"./context-compaction\";\n\n// Shared LLM factory for both OpenAI-compatible and Anthropic-compatible\n// endpoints. Auto-detects Anthropic via baseUrl substring; explicit\n// `providerType` overrides.\nexport {\n\tcreateLanguageModel,\n\tdetectProviderType,\n\tnormalizeAnthropicBaseUrl,\n\treadLLMEnv,\n} from \"./llm-factory\";\nexport type { LLMEnvDefaults, LLMProviderType, LanguageModelFactoryOptions } from \"./llm-factory\";\n\n// ─── 3. Retrieval: chunking, embeddings, vector stores, parsers ──────────\nexport {\n\tchunkText,\n\tcountTokens,\n\tgetOptimalChunkSize,\n\testimateChunkCount,\n\tgenerateEmbedding,\n\tgenerateEmbeddings,\n\tcosineSimilarity,\n\tgetEmbeddingDimensions,\n\tgetEmbeddingModel,\n\tgetModelPricing,\n\tgetVectorStore,\n\taddDocumentToVectorStore,\n\tsearchVectorStore,\n\tsearchHybridVectorStore,\n\tdeleteDocumentFromVectorStore,\n\tgetVectorStoreStats,\n\tconfigureVectorService,\n\tUniversalEmbeddings,\n\tTextLoader,\n\tAppleDocumentLoader,\n\tparseFile,\n\tparseFileToDocument,\n\tgetPdfPageCount,\n\tshouldUseNativePdf,\n\tisSupportedContentType,\n\tconfigureParsers,\n\tSQLiteVecStore,\n\tgetSQLiteVecStore,\n\tresetSQLiteVecStore,\n\tChromaVectorStore,\n\tHybridSearchAdapter,\n\tfuseHybridResults,\n\tLanceDBStore,\n\tMilvusStore,\n} from \"@melandlabs/rag\";\n\nexport type {\n\tChunkOptions,\n\tTextChunk,\n\tEmbeddingResult,\n\tIVectorStore,\n\tSearchResult,\n\tFileContent,\n\tParsersConfig,\n\tVectorSearchResult,\n\tDocumentChunk,\n\tChromaVectorStoreOptions,\n\tIHybridVectorStore,\n\tHybridSearchFilter,\n\tHybridSearchQuery,\n\tHybridFusionStrategy,\n\tHybridRetrievalConfig,\n\tVectorStoreBackend,\n\tVectorServiceConfig,\n\tHybridFusionInput,\n\tHybridSearchAdapterOptions,\n\tLexicalSearchProvider,\n\tLanceDBFtsOptions,\n\tLanceDBStoreOptions,\n\tMilvusStoreOptions,\n} from \"@melandlabs/rag\";\n\n// ─── 3b. Cloud / local embedding provider abstraction ─────────────────────\n// Re-exported from `@melandlabs/ai-rag`, an **optional** peer dep. The\n// factory `getConfiguredEmbeddingProvider()` honours the\n// `EMBEDDING_PROVIDER` env var (`cloud` default | `local`) and returns\n// a `LocalTransformersEmbeddingProvider` (ONNX via @huggingface/transformers,\n// default model `Xenova/all-MiniLM-L6-v2`, 384 dims) or a `CloudEmbeddingProvider`\n// (OpenRouter-compatible, default model `text-embedding-3-small`, 1536 dims).\n//\n// Host apps that need local embeddings must install `@melandlabs/ai-rag`\n// themselves; if they don't, these bindings resolve to undefined at\n// runtime and importing them will throw — same shape as the rest of the\n// facade's optional peer deps.\nexport {\n\tgetConfiguredEmbeddingProvider,\n\tgetConfiguredEmbeddingModelName,\n\tgetEmbeddingProviderType,\n\tCloudEmbeddingProvider,\n} from \"@melandlabs/ai-rag/embedding-provider\";\nexport type {\n\tCloudEmbeddingProviderOptions,\n\tEmbeddingProvider,\n\tEmbeddingProviderFactoryOptions,\n\tEmbeddingProviderType,\n} from \"@melandlabs/ai-rag/embedding-provider\";\n// The local class is re-exported from its dedicated subpath (the\n// embedding-provider subpath intentionally does not re-export it).\nexport {\n\tLocalTransformersEmbeddingProvider,\n\ttype LocalTransformersEmbeddingProviderOptions,\n} from \"@melandlabs/ai-rag/local-transformers-embedding-provider\";\n\n// ─── 4. Loop engine: filesystem paths, CLI paths, preferences ────────────\nexport * from \"@melandlabs/loop\";\n\n// ─── 5. Agent runtime: every ai export except the conflicting UserType ────\n// `UserType` from `@melandlabs/ai` is renamed to `AIUserType` here.\nexport * from \"./ai-reexport\";\n\n// ─── 6. Cron: scheduling primitives ────────────────────────────────────────\nexport {\n\tcomputeNextRun,\n\tcreateJobExecutionStreamResponse,\n\tformatDate,\n\tisJobDue,\n\tparseDate,\n\tvalidateCronExpression,\n} from \"@melandlabs/cron\";\nexport type {\n\tCronJob,\n\tExecuteJobOptions,\n\tJobAgentStreamEvent,\n\tJobConfig,\n\tJobExecutionContext,\n\tJobExecutionResult,\n\tJobTimezoneSource,\n\tScheduleConfig,\n\tScheduledJobLike,\n\tSchedulerConfig,\n\tSchedulerEvent,\n} from \"@melandlabs/cron\";\n\n// ─── 7. Search: live web search + query classifier ────────────────────────\nexport { needsRealTimeInfo, search } from \"@melandlabs/search\";\n// SearchResult collides with the identically-named type from @melandlabs/rag;\n// expose it under a web-search-specific name on the facade.\nexport type { SearchResult as WebSearchResult, SearchType } from \"@melandlabs/search\";\n\n// ─── 8. Audit: structured operation logging ────────────────────────────────\nexport {\n\tAUDIT_LOG_PATH,\n\tclearAuditLogs,\n\tinstallAuditInterceptors,\n\tlogCommandExec,\n\tlogCredentialAccess,\n\tlogFileRead,\n\treadAuditLogs,\n} from \"@melandlabs/audit\";\nexport type { AuditEntry, CredentialAccessEntry } from \"@melandlabs/audit\";\n\n// ─── 9. Voice: browser-oriented TTS / STT plugins ─────────────────────────\nexport { KokoroPlugin } from \"@melandlabs/voice-kokoro\";\nexport { WhisperPlugin } from \"@melandlabs/voice-whisper\";\nexport type {\n\tWhisperPluginOptions,\n\tWhisperTranscriptionInput,\n\tWhisperTranscriptionResult,\n} from \"@melandlabs/voice-whisper\";\n\n// Tutorial-compatibility aliases for APIs that were renamed after the docs were written.\nexport { KokoroPlugin as LocalKokoroTTS } from \"@melandlabs/voice-kokoro\";\nexport { WhisperPlugin as LocalWhisperSTT } from \"@melandlabs/voice-whisper\";\n\n// ─── 10. Security: token encryption + SSRF protection ───────────────────────\nexport {\n\tSSRFValidationError,\n\tTokenEncryption,\n\tdecryptToken,\n\tdecryptTokenPair,\n\tencryptToken,\n\tencryptTokenPair,\n\tfetchWithSSRFProtection,\n\tisTrustedStorageUrl,\n\tvalidateUrlForSSRF,\n} from \"@melandlabs/security\";\nexport type { DerivedKey } from \"@melandlabs/security\";\n\n// ─── 11. Integrations: platform context factory ─────────────────────────────\nexport { createMinimalContext } from \"@melandlabs/integrations/core\";\nexport type {\n\tAIHandler,\n\tAIHandlerOptions,\n\tAppConfigProvider,\n\tAttachmentDownloadPayload,\n\tAuthProvider,\n\tBaileysAuthStateProvider,\n\tBot,\n\tClientRegistry,\n\tCloudSyncProvider,\n\tConfigProvider,\n\tCredentialStore,\n\tFileIngester,\n\tInboundMessageHandler,\n\tIngestExternalOptions,\n\tIngestResult,\n\tIngestedAttachment,\n\tIntegrationAccount,\n\tIntegrationAccountWithBot,\n\tIntegrationContext,\n\tLocalUserType,\n\tPlatformId,\n\tSessionStore,\n} from \"@melandlabs/integrations/core\";\n\n// Tutorial-compatibility aliases for integration APIs that were renamed.\nexport { createMinimalContext as getIntegrationManager } from \"@melandlabs/integrations/core\";\n\n// ─── 12. CLI entry points (used by the bundled bin scripts in dist/cli/) ──\n// Re-export the server starters so the CLI bins can import them through\n// the facade's main bundle (one canonical copy of the code).\nexport { startHttpServer } from \"@melandlabs/memory-store/http\";\nexport { startMcpServer } from \"@melandlabs/memory-store/mcp\";\n\n// ─── 13. OKF v0.2 (Open Knowledge Format) importer / exporter ──────────\n// Markdown + YAML-front-matter ⇄ RawMessage codec. The HTTP and MCP\n// front-ends re-use the same `RawMessageStore` so a host that already\n// runs `opencontext http` / `opencontext mcp` can serve `POST\n// /v1/okf/import` and `memory.okfImport` without extra wiring.\nexport {\n\tparseOkf,\n\tparseOkfFrontMatter,\n\tstringifyOkf,\n\tvalidateOkfFrontMatter,\n\tokfToRawMessage,\n\trawMessageToOkf,\n\tokfTypeToFactType,\n\tfactTypeToOkfType,\n\textractMarkdownLinks,\n\tslugify,\n\tingestOkfString,\n\treadOkfPackage,\n\twriteOkfPackage,\n\tOkfError,\n\tokfIssue,\n\tparseOkfArgs,\n\tstartOkf,\n\tstartOkfServe,\n\tfeedOkfServe,\n\tserveOkf,\n\tprintOkfHelp,\n\tbuildGraphFromMessages,\n\tbuildGraphFromDir,\n\tisOkfType,\n\tOkfFrontMatterSchema,\n\tOkfDocumentSchema,\n\tOkfPackageManifestSchema,\n\tOKF_TYPES,\n} from \"@melandlabs/okf\";\nexport type {\n\tOkfFrontMatter,\n\tOkfDocument,\n\tOkfPackageManifest,\n\tOkfSource,\n\tOkfVerification,\n\tOkfGenerated,\n\tOkfIssue,\n\tOkfIssueCode,\n\tParsedOkfDocument,\n\tOkfToRawMessageOptions,\n\tOkfToRawMessageResult,\n\tRawMessageToOkfOptions,\n\tRawMessageToOkfResult,\n\tReadOkfPackageOptions,\n\tOkfPackageFile,\n\tReadOkfPackageResult,\n\tWriteOkfPackageOptions,\n\tWriteOkfPackageResult,\n\tOkfAction,\n\tOkfCommonOptions,\n\tOkfIngestOptions,\n\tOkfEmitOptions,\n\tOkfValidateOptions,\n\tOkfInspectOptions,\n\tOkfServeOptions,\n\tOkfServeStartOptions,\n\tStartedOkfServe,\n\tOkfHelpOptions,\n\tOkfOptions,\n\tOkfRunResult,\n\tOkfRunOptions,\n\tOkfIngestSummary,\n\tOkfEmitSummary,\n\tOkfValidateSummary,\n\tOkfInspectSummary,\n\tOkfInspectOutput,\n\tWikiGraph,\n\tWikiNode,\n\tWikiEdge,\n\tBuildGraphOptions,\n} from \"@melandlabs/okf\";\n\n// ─── 14. Workspace — versioned, cross-file folder knowledge ──\n// The single-package facade exposes the three core APIs (`updateWorkspaceContext`,\n// `searchWorkspaceContext`, `listWorkspaceResources`) so consumers don't need a\n// separate install. Storage is delegated to the shared SQLite DB the memory\n// store already owns (`~/.opencontext/memory/store.db`); embedding fan-out is\n// async and honours `EMBEDDING_PROVIDER=local|cloud` via the optional peer\n// dep `@melandlabs/ai-rag` (local = `Xenova/all-MiniLM-L6-v2`, 384 dims;\n// cloud = OpenRouter, 1536 dims).\n//\n// Surface is JS-API + CLI only; HTTP / MCP transport lives behind the\n// `opencontext workspace …` subcommand (`@melandlabs/workspace/cli`).\nexport {\n\tupdateWorkspaceContext,\n\tsearchWorkspaceContext,\n\tlistWorkspaceResources,\n\tresolveWorkspaceCitation,\n\tdistillResource,\n\tpromoteFactsToPage,\n\tgetSQLiteWorkspaceStore,\n\tcloseSQLiteWorkspaceStore,\n\tresolveWorkspaceDbPath,\n\tgetWorkspaceEmbeddingProvider,\n\tworkspaceEmbedQuery,\n\tworkspaceEmbedDocuments,\n\tworkspaceEmbeddingModelName,\n\tworkspaceEmbeddingDimensions,\n} from \"@melandlabs/workspace\";\nexport type {\n\tRuntimeContext,\n\tWorkspaceStorageKind,\n\tWorkspaceEdgeType,\n\tWorkspaceIndexStatus,\n\tWorkspaceSearchStrategy,\n\tWorkspaceResource,\n\tWorkspaceResourceVersion,\n\tWorkspaceChunk,\n\tWorkspaceReferenceEdge,\n\tWorkspaceJob,\n\tEdgeProvenance,\n\tWorkspaceSearchHit,\n\tSearchWorkspaceContextOptions,\n\tUpdateWorkspaceContextInput,\n\tUpdateWorkspaceContextResult,\n\tSearchWorkspaceContextInput,\n\tSearchWorkspaceContextResult,\n\tListWorkspaceResourcesInput,\n\tListWorkspaceResourcesResult,\n\tOkfFolderResource,\n\tWorkspaceEmbeddingProvider,\n\tWorkspaceEmbeddingProviderType,\n\tDistillResourceInput,\n\tDistillResourceOutput,\n\tDistilledEdgeProposal,\n\tPromoteFactsInput,\n\tPromoteFactsOutput,\n\tPromotedFact,\n\tResolveWorkspaceCitationDeps,\n\tCrossLayerResolvedCitation,\n} from \"@melandlabs/workspace\";\n"
    },
    {
      "path": "packages/security/src/token-encryption.ts",
      "content": "import * as crypto from \"node:crypto\";\nimport * as FernetImport from \"fernet\";\n\nconst Fernet = ((FernetImport as unknown as { default?: typeof FernetImport }).default ??\n\tFernetImport) as typeof FernetImport;\n\nexport class TokenEncryption {\n\tprivate fernetSecret?: FernetImport.Secret;\n\tprivate encryptionKey?: Buffer;\n\tprivate ttl: number;\n\n\tconstructor() {\n\t\tconst TTL_SECONDS = Number(process.env.FERNET_TTL_SECONDS) || 3153600000;\n\t\tthis.ttl = TTL_SECONDS;\n\t}\n\n\t/**\n\t * Gets or creates the encryption key from environment variables\n\t * @returns Buffer containing the encryption key\n\t */\n\tprivate getEncryptionKey(): Buffer {\n\t\tif (this.encryptionKey) {\n\t\t\treturn this.encryptionKey;\n\t\t}\n\n\t\tconst envKey = process.env.ENCRYPTION_KEY;\n\t\tif (!envKey) {\n\t\t\tthrow new Error(\"No encryption key available. Set ENCRYPTION_KEY environment variable.\");\n\t\t}\n\n\t\ttry {\n\t\t\t// Try to use as a direct Fernet key\n\t\t\tconst testKey = Buffer.from(envKey);\n\t\t\t// Simple validation of Fernet key format (32 URL-safe Base64 encoded bytes)\n\t\t\tif (testKey.length === 32) {\n\t\t\t\tthis.encryptionKey = testKey;\n\t\t\t} else {\n\t\t\t\tthrow new Error(\"Key length is not valid for Fernet\");\n\t\t\t}\n\t\t} catch {\n\t\t\t// If not a valid Fernet key, derive from password\n\t\t\tconst derivedKey = this.deriveKeyFromPassword(Buffer.from(envKey));\n\t\t\tthis.encryptionKey = derivedKey;\n\t\t}\n\n\t\treturn this.encryptionKey;\n\t}\n\n\t/**\n\t * Derives an encryption key from a password using PBKDF2\n\t * @param password Buffer containing the password\n\t * @param salt Optional salt value\n\t * @returns The derived key\n\t */\n\tprivate deriveKeyFromPassword(password: Buffer, salt?: Buffer): Buffer {\n\t\tconst calSalt = salt ? salt : Buffer.from(\"mypraxos-salt\");\n\n\t\treturn crypto.pbkdf2Sync(password, calSalt, 100000, 32, \"sha256\");\n\t}\n\n\t/**\n\t * Gets the Fernet Secret instance (cached)\n\t * @returns Fernet Secret instance\n\t */\n\tprivate getFernetSecret(): FernetImport.Secret {\n\t\tif (!this.fernetSecret) {\n\t\t\tconst keyBytes = this.getEncryptionKey();\n\t\t\tthis.fernetSecret = new Fernet.Secret(keyBytes.toString(\"base64\"));\n\t\t}\n\t\treturn this.fernetSecret;\n\t}\n\n\t/**\n\t * Encrypts a token string\n\t * @param token Plaintext token to encrypt\n\t * @returns Base64 encoded encrypted token\n\t */\n\tencryptToken(token: string): string {\n\t\tconst secret = this.getFernetSecret();\n\n\t\t// Create a new Token instance for each encryption to avoid state issues\n\t\tconst fernetToken = new Fernet.Token({\n\t\t\tsecret,\n\t\t\tttl: this.ttl,\n\t\t});\n\n\t\t// Fernet's encode method automatically handles encryption\n\t\tconst encrypted = fernetToken.encode(token);\n\t\treturn encrypted;\n\t}\n\n\t/**\n\t * Decrypts an encrypted token\n\t * @param encryptedToken Base64 encoded encrypted token\n\t * @returns Plaintext token\n\t */\n\tdecryptToken(encryptedToken: string): string {\n\t\tconst secret = this.getFernetSecret();\n\n\t\t// Create a new Token instance for each decryption to avoid state issues\n\t\tconst fernetToken = new Fernet.Token({\n\t\t\tsecret,\n\t\t\ttoken: encryptedToken,\n\t\t\tttl: this.ttl,\n\t\t});\n\n\t\t// Fernet's decode method automatically handles decryption\n\t\tconst decrypted = fernetToken.decode();\n\n\t\treturn decrypted as string;\n\t}\n\n\t/**\n\t * Encrypts a pair of access and refresh tokens\n\t * @param accessToken Access token to encrypt\n\t * @param refreshToken Optional refresh token to encrypt\n\t * @returns Encrypted token pair\n\t */\n\tencryptTokenPair(accessToken: string, refreshToken?: string): [string, string | null] {\n\t\tconst encryptedAccess = this.encryptToken(accessToken);\n\t\tconst encryptedRefresh = refreshToken ? this.encryptToken(refreshToken) : null;\n\n\t\treturn [encryptedAccess, encryptedRefresh];\n\t}\n\n\t/**\n\t * Decrypts a pair of access and refresh tokens\n\t * @param encryptedAccessToken Encrypted access token\n\t * @param encryptedRefreshToken Optional encrypted refresh token\n\t * @returns Decrypted token pair\n\t */\n\tdecryptTokenPair(encryptedAccessToken: string, encryptedRefreshToken?: string): [string, string | null] {\n\t\tconst accessToken = this.decryptToken(encryptedAccessToken);\n\t\tconst refreshToken = encryptedRefreshToken ? this.decryptToken(encryptedRefreshToken) : null;\n\t\treturn [accessToken, refreshToken];\n\t}\n}\n\n// Global instance\nconst tokenEncryption = new TokenEncryption();\n\n// Convenience functions\nexport function encryptToken(token: string): string {\n\treturn tokenEncryption.encryptToken(token);\n}\n\nexport function decryptToken(encryptedToken: string): string {\n\treturn tokenEncryption.decryptToken(encryptedToken);\n}\n\nexport function encryptTokenPair(accessToken: string, refreshToken?: string): [string, string | null] {\n\treturn tokenEncryption.encryptTokenPair(accessToken, refreshToken);\n}\n\nexport function decryptTokenPair(\n\tencryptedAccessToken: string,\n\tencryptedRefreshToken?: string,\n): [string, string | null] {\n\treturn tokenEncryption.decryptTokenPair(encryptedAccessToken, encryptedRefreshToken);\n}\n"
    },
    {
      "path": "packages/security/src/url-validator.ts",
      "content": "/**\n * SSRF Protection Utilities\n * Prevents Server-Side Request Forgery by validating URLs against\n * private IP ranges and enforcing domain whitelists where appropriate.\n */\n\n/**\n * Private IP ranges that should be blocked\n */\nconst PRIVATE_IP_RANGES = [\n\t// IPv4 private ranges\n\t{ start: \"10.0.0.0\", end: \"10.255.255.255\", mask: 8 }, // 10.0.0.0/8 - Private Class A\n\t{ start: \"172.16.0.0\", end: \"172.31.255.255\", mask: 12 }, // 172.16.0.0/12 - Private Class B\n\t{ start: \"192.168.0.0\", end: \"192.168.255.255\", mask: 16 }, // 192.168.0.0/16 - Private Class C\n\t{ start: \"127.0.0.0\", end: \"127.255.255.255\", mask: 8 }, // 127.0.0.0/8 - Loopback\n\t{ start: \"0.0.0.0\", end: \"0.255.255.255\", mask: 8 }, // 0.0.0.0/8 - Current network\n\t{ start: \"100.64.0.0\", end: \"100.127.255.255\", mask: 10 }, // 100.64.0.0/10 - Carrier-grade NAT\n\t{ start: \"169.254.0.0\", end: \"169.254.255.255\", mask: 16 }, // 169.254.0.0/16 - Link-local\n\t{ start: \"192.0.0.0\", end: \"192.0.2.255\", mask: 24 }, // 192.0.2.0/24 - TEST-NET-1\n\t{ start: \"198.51.100.0\", end: \"198.51.100.255\", mask: 24 }, // 198.51.100.0/24 - TEST-NET-2\n\t{ start: \"203.0.113.0\", end: \"203.0.113.255\", mask: 24 }, // 203.0.113.0/24 - TEST-NET-3\n\t{ start: \"224.0.0.0\", end: \"255.255.255.255\", mask: 4 }, // 224.0.0.0/4 - Multicast/Reserved\n];\n\n/**\n * Convert IPv4 string to number for comparison\n */\nfunction ipToInt(ip: string): number {\n\tconst parts = ip.split(\".\").map(Number);\n\treturn ((parts[0] ?? 0) << 24) | ((parts[1] ?? 0) << 16) | ((parts[2] ?? 0) << 8) | (parts[3] ?? 0);\n}\n\n/**\n * Check if an IP address is within a private range\n */\nfunction isPrivateIp(ip: string): boolean {\n\t// Check IPv6\n\tif (ip.includes(\":\")) {\n\t\t// Block IPv6 loopback, link-local, unique local, and documentation ranges\n\t\treturn (\n\t\t\tip.startsWith(\"::\") ||\n\t\t\tip.startsWith(\"fe80:\") || // Link-local\n\t\t\tip.startsWith(\"fc00:\") || // Unique local\n\t\t\tip.startsWith(\"fd00:\") || // Unique local\n\t\t\tip.startsWith(\"fd\") || // Unique local prefix\n\t\t\tip.startsWith(\"2001:db8:\") // Documentation\n\t\t);\n\t}\n\n\t// Check IPv4\n\tconst ipNum = ipToInt(ip);\n\treturn PRIVATE_IP_RANGES.some((range) => {\n\t\tconst start = ipToInt(range.start);\n\t\tconst end = ipToInt(range.end);\n\t\treturn ipNum >= start && ipNum <= end;\n\t});\n}\n\n/**\n * Check if a hostname resolves to a private IP\n * Note: This performs DNS resolution which could be slow,\n * so use judiciously and consider caching\n */\nasync function isPrivateHostname(hostname: string): Promise<boolean> {\n\ttry {\n\t\t// Skip IP addresses (they're already checked)\n\t\tif (/^[\\d\\.:]+$/.test(hostname)) {\n\t\t\treturn isPrivateIp(hostname);\n\t\t}\n\n\t\t// For hostnames, we check for known patterns\n\t\t// This is a safer approach than DNS resolution which could be abused\n\t\tconst localhostPatterns = [\n\t\t\t\"localhost\",\n\t\t\t\"local\",\n\t\t\t\"localdomain\",\n\t\t\t\"internal\",\n\t\t\t\"intranet\",\n\t\t\t\"corp\",\n\t\t\t\"private\",\n\t\t\t\"dmz\",\n\t\t];\n\n\t\tconst lowerHostname = hostname.toLowerCase();\n\t\tif (localhostPatterns.some((pattern) => lowerHostname.includes(pattern))) {\n\t\t\treturn true;\n\t\t}\n\n\t\t// Check if hostname is in the TLD list that shouldn't be used\n\t\tconst suspiciousTlds = [\".test\", \".example\", \".invalid\", \".localhost\"];\n\t\tif (suspiciousTlds.some((tld) => lowerHostname.endsWith(tld))) {\n\t\t\treturn true;\n\t\t}\n\n\t\t// For external hostnames, we rely on DNSSEC and other infrastructure\n\t\t// This is a basic check - in production you might want to implement\n\t\t// a DNSSEC-validating resolver or use a dedicated service\n\t\treturn false;\n\t} catch {\n\t\treturn true; // Fail closed on errors\n\t}\n}\n\n/**\n * SSRF validation error\n */\nexport class SSRFValidationError extends Error {\n\tconstructor(message: string) {\n\t\tsuper(message);\n\t\tthis.name = \"SSRFValidationError\";\n\t}\n}\n\n/**\n * Allowed domains for file storage providers\n */\nconst ALLOWED_STORAGE_DOMAINS = [\n\t\"*.vercel-storage.com\",\n\t\"*.blob.vercel-storage.com\",\n\t\"*.vercel.com\",\n\t\"googleapis.com\",\n\t\"*.googleapis.com\",\n\t\"*.googleusercontent.com\",\n\t\"drive.google.com\",\n\t\"*.drive.google.com\",\n\t\"notion.so\",\n\t\"*.notion.so\",\n\t\"*.notion-static.com\",\n\t\"files.slack.com\",\n\t\"*.files.slack.com\",\n\t\"*.amazonaws.com\", // S3 endpoints\n];\n\n/**\n * Validate a URL for SSRF risks\n * @param url - The URL to validate\n * @param options - Validation options\n * @returns The parsed and validated URL\n * @throws {SSRFValidationError} if the URL is invalid or potentially dangerous\n */\nexport async function validateUrlForSSRF(\n\turl: string,\n\toptions: {\n\t\t/** Require HTTPS protocol */\n\t\trequireHttps?: boolean;\n\t\t/** Strict whitelist mode - only allow known storage domains */\n\t\tstrictWhitelist?: boolean;\n\t\t/** Additional allowed domains */\n\t\tallowedDomains?: string[];\n\t} = {},\n): Promise<URL> {\n\tconst { requireHttps = true, strictWhitelist = true, allowedDomains = [] } = options;\n\n\t// Parse URL\n\tlet parsed: URL;\n\ttry {\n\t\tparsed = new URL(url);\n\t} catch {\n\t\tthrow new SSRFValidationError(\"Invalid URL format\");\n\t}\n\n\t// Validate protocol\n\tif (requireHttps && parsed.protocol !== \"https:\") {\n\t\tthrow new SSRFValidationError(\"Only HTTPS URLs are allowed\");\n\t}\n\n\t// Block non-http/https protocols\n\tif (![\"http:\", \"https:\"].includes(parsed.protocol)) {\n\t\tthrow new SSRFValidationError(`Protocol ${parsed.protocol} is not allowed`);\n\t}\n\n\t// Check for private IP addresses in hostname\n\tif (await isPrivateHostname(parsed.hostname)) {\n\t\tthrow new SSRFValidationError(\"Access to private IP addresses or local resources is not allowed\");\n\t}\n\n\t// If strict whitelist mode is enabled, check against allowed domains\n\tif (strictWhitelist) {\n\t\tconst allAllowedDomains = [...ALLOWED_STORAGE_DOMAINS, ...allowedDomains];\n\t\tlet isAllowed = false;\n\n\t\tfor (const pattern of allAllowedDomains) {\n\t\t\tconst lowerHostname = parsed.hostname.toLowerCase();\n\t\t\tif (pattern.startsWith(\"*.\")) {\n\t\t\t\tconst baseDomain = pattern.slice(2);\n\t\t\t\tif (lowerHostname === baseDomain || lowerHostname.endsWith(`.${baseDomain}`)) {\n\t\t\t\t\tisAllowed = true;\n\t\t\t\t\tbreak;\n\t\t\t\t}\n\t\t\t} else if (lowerHostname === pattern) {\n\t\t\t\tisAllowed = true;\n\t\t\t\tbreak;\n\t\t\t}\n\t\t}\n\n\t\tif (!isAllowed) {\n\t\t\tthrow new SSRFValidationError(`Domain ${parsed.hostname} is not in the allowed list`);\n\t\t}\n\t}\n\n\t// Check for URL rebinding attacks (redirects to private IPs)\n\t// We validate the URL before fetching, but also need to handle redirects\n\t// This is handled by the fetchWithSSRFProtection function below\n\n\treturn parsed;\n}\n\n/**\n * Fetch a URL with SSRF protection\n * This validates the URL before fetching and also validates any redirects\n */\nexport async function fetchWithSSRFProtection(\n\turl: string,\n\toptions: {\n\t\trequireHttps?: boolean;\n\t\tstrictWhitelist?: boolean;\n\t\tallowedDomains?: string[];\n\t\tmaxRedirects?: number;\n\t\tfetchOptions?: RequestInit;\n\t} = {},\n): Promise<Response> {\n\tconst {\n\t\trequireHttps = true,\n\t\tstrictWhitelist = true,\n\t\tallowedDomains = [],\n\t\tmaxRedirects = 5,\n\t\tfetchOptions = {},\n\t} = options;\n\n\tlet currentUrl = url;\n\tlet redirectCount = 0;\n\n\twhile (redirectCount <= maxRedirects) {\n\t\t// Validate the current URL\n\t\tconst validatedUrl = await validateUrlForSSRF(currentUrl, {\n\t\t\trequireHttps,\n\t\t\tstrictWhitelist,\n\t\t\tallowedDomains,\n\t\t});\n\n\t\t// Fetch the URL with redirect: manual\n\t\tconst response = await fetch(validatedUrl.toString(), {\n\t\t\t...fetchOptions,\n\t\t\tredirect: \"manual\",\n\t\t});\n\n\t\t// If not a redirect, return the response\n\t\tif (response.status === 0 || (response.status >= 200 && response.status < 300)) {\n\t\t\treturn response;\n\t\t}\n\n\t\t// Handle redirects\n\t\tif (\n\t\t\tresponse.status === 301 ||\n\t\t\tresponse.status === 302 ||\n\t\t\tresponse.status === 307 ||\n\t\t\tresponse.status === 308\n\t\t) {\n\t\t\tconst location = response.headers.get(\"Location\");\n\t\t\tif (!location) {\n\t\t\t\tthrow new SSRFValidationError(\"Redirect without Location header\");\n\t\t\t}\n\n\t\t\t// Handle relative redirects\n\t\t\tcurrentUrl = location.startsWith(\"http\") ? location : new URL(location, validatedUrl).toString();\n\n\t\t\tredirectCount++;\n\n\t\t\t// Too many redirects\n\t\t\tif (redirectCount > maxRedirects) {\n\t\t\t\tthrow new SSRFValidationError(\"Too many redirects\");\n\t\t\t}\n\n\t\t\tcontinue;\n\t\t}\n\n\t\t// Other status codes\n\t\treturn response;\n\t}\n\n\tthrow new SSRFValidationError(\"Invalid redirect state\");\n}\n\n/**\n * Check if a URL is from a known, trusted storage provider\n * Used for less strict validation when we know the URL came from a trusted source\n */\nexport function isTrustedStorageUrl(url: string): boolean {\n\ttry {\n\t\tconst parsed = new URL(url);\n\t\tconst hostname = parsed.hostname.toLowerCase();\n\n\t\t// Vercel Blob URLs\n\t\tif (hostname.includes(\"vercel-storage.com\")) return true;\n\n\t\t// Google Drive/Storage\n\t\tif (hostname.endsWith(\".googleapis.com\")) return true;\n\t\tif (hostname.endsWith(\".googleusercontent.com\")) return true;\n\t\tif (hostname === \"drive.google.com\") return true;\n\n\t\t// Notion\n\t\tif (hostname.endsWith(\"notion.so\")) return true;\n\t\tif (hostname.endsWith(\"notion-static.com\")) return true;\n\n\t\t// Slack\n\t\tif (hostname.includes(\"files.slack.com\")) return true;\n\n\t\t// AWS S3 (any S3 endpoint)\n\t\tif (hostname.includes(\".amazonaws.com\")) return true;\n\n\t\treturn false;\n\t} catch {\n\t\treturn false;\n\t}\n}\n"
    },
